(()=>{'use strict';
const DB='ccner-level1-memory',VER=1,STORE='media';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c])),uid=p=>`${p}-${Date.now()}-${Math.random().toString(36).slice(2,9)}`;
let db=null,stories=[],music=[],recorder=null,recChunks=[],recStarted=0,activeAudio=null;
const labels={'en-IN':{stories:'Family Stories',music:'Music Memory',addStory:'Add family story',record:'Record story',upload:'Upload recording',title:'Story title',save:'Save memory',cancel:'Cancel',play:'Play',delete:'Delete',emptyStory:'No family stories saved yet.',emptyMusic:'No music memories saved yet.',addMusic:'Add music memory',musicTitle:'Music title',region:'Region / language',association:'Why is this familiar?',privacy:'Only use recordings and music that the family/user has permission to store and replay.',recording:'Recording…',stop:'Stop recording',notSupported:'Recording is not available in this browser. You can upload an existing recording.',family:'Family memory',folk:'Regional / folk',familiar:'Familiar music',sound:'Cultural sound',cue:'Memory cue',momo:'Momo can bring back a saved memory when it fits the conversation.'},'hi-IN':{stories:'परिवार की यादें',music:'म्यूज़िक मेमोरी',addStory:'परिवार की कहानी जोड़ें',record:'कहानी रिकॉर्ड करें',upload:'रिकॉर्डिंग अपलोड करें',title:'कहानी का नाम',save:'याद सहेजें',cancel:'रद्द करें',play:'चलाएँ',delete:'हटाएँ',emptyStory:'अभी कोई पारिवारिक कहानी सहेजी नहीं गई है।',emptyMusic:'अभी कोई संगीत याद नहीं सहेजी गई है।',addMusic:'संगीत याद जोड़ें',musicTitle:'संगीत का नाम',region:'क्षेत्र / भाषा',association:'यह क्यों परिचित है?',privacy:'केवल वही रिकॉर्डिंग और संगीत सहेजें जिनका उपयोग करने की अनुमति हो।',recording:'रिकॉर्ड हो रहा है…',stop:'रिकॉर्डिंग रोकें',notSupported:'इस ब्राउज़र में रिकॉर्डिंग उपलब्ध नहीं है। मौजूदा रिकॉर्डिंग अपलोड करें।',family:'परिवार की याद',folk:'क्षेत्रीय / लोक',familiar:'परिचित संगीत',sound:'सांस्कृतिक ध्वनि',cue:'याद संकेत',momo:'बातचीत के संदर्भ में Momo सहेजी गई याद चला सकता है।'},'bn-IN':{stories:'পরিবারের স্মৃতি',music:'মিউজিক মেমরি',addStory:'পরিবারের গল্প যোগ করুন',record:'গল্প রেকর্ড করুন',upload:'রেকর্ডিং আপলোড করুন',title:'গল্পের নাম',save:'স্মৃতি সংরক্ষণ',cancel:'বাতিল',play:'চালান',delete:'মুছুন',emptyStory:'এখনও কোনো পরিবারের গল্প সংরক্ষিত নেই।',emptyMusic:'এখনও কোনো মিউজিক মেমরি নেই।',addMusic:'মিউজিক মেমরি যোগ করুন',musicTitle:'মিউজিকের নাম',region:'অঞ্চল / ভাষা',association:'কেন এটি পরিচিত?',privacy:'যে রেকর্ডিং ও মিউজিক ব্যবহারের অনুমতি আছে শুধু সেগুলোই সংরক্ষণ করুন।',recording:'রেকর্ড হচ্ছে…',stop:'রেকর্ডিং থামান',notSupported:'এই ব্রাউজারে রেকর্ডিং নেই। একটি রেকর্ডিং আপলোড করুন।',family:'পরিবারের স্মৃতি',folk:'আঞ্চলিক / লোক',familiar:'পরিচিত মিউজিক',sound:'সাংস্কৃতিক শব্দ',cue:'স্মৃতি সংকেত',momo:'প্রাসঙ্গিক কথোপকথনে Momo সংরক্ষিত স্মৃতি ফিরিয়ে আনতে পারে।'},'as-IN':{stories:'পৰিয়ালৰ স্মৃতি',music:'মিউজিক মেমৰি',addStory:'পৰিয়ালৰ কাহিনী যোগ কৰক',record:'কাহিনী ৰেকৰ্ড কৰক',upload:'ৰেকৰ্ডিং আপলোড কৰক',title:'কাহিনীৰ নাম',save:'স্মৃতি সংৰক্ষণ',cancel:'বাতিল',play:'চলাওক',delete:'মচক',emptyStory:'এতিয়ালৈ কোনো পৰিয়ালৰ কাহিনী সংৰক্ষিত হোৱা নাই।',emptyMusic:'এতিয়ালৈ কোনো মিউজিক স্মৃতি নাই।',addMusic:'মিউজিক স্মৃতি যোগ কৰক',musicTitle:'মিউজিকৰ নাম',region:'অঞ্চল / ভাষা',association:'ই কিয় পৰিচিত?',privacy:'অনুমতি থকা ৰেকৰ্ডিং আৰু মিউজিকহে সংৰক্ষণ কৰক।',recording:'ৰেকৰ্ড হৈ আছে…',stop:'ৰেকৰ্ডিং ৰখাওক',notSupported:'এই ব্ৰাউজাৰত ৰেকৰ্ডিং উপলব্ধ নহয়। এটা ৰেকৰ্ডিং আপলোড কৰক।',family:'পৰিয়ালৰ স্মৃতি',folk:'আঞ্চলিক / লোক',familiar:'পৰিচিত মিউজিক',sound:'সাংস্কৃতিক শব্দ',cue:'স্মৃতি সংকেত',momo:'প্ৰাসংগিক কথোপকথনত Momo-ই সংৰক্ষিত স্মৃতি ঘূৰাই আনিব পাৰে।'}};
function lang(){try{const p=JSON.parse(localStorage.getItem('ccner-p1-profile')||'{}');return localStorage.getItem('ccner-p1-language')||p.preferredLanguage||'en-IN'}catch(_){return'en-IN'}}
function t(k){return(labels[lang()]||labels['en-IN'])[k]||labels['en-IN'][k]||k}
function openDB(){return new Promise((res,rej)=>{if(db)return res(db);if(!window.indexedDB)return rej(new Error('IndexedDB unavailable'));const r=indexedDB.open(DB,VER);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains(STORE)){const s=d.createObjectStore(STORE,{keyPath:'id'});s.createIndex('kind','kind')}};r.onsuccess=()=>{db=r.result;res(db)};r.onerror=()=>rej(r.error)})}
function obj(mode){return db.transaction(STORE,mode).objectStore(STORE)}
async function all(kind){await openDB();return new Promise((res,rej)=>{const q=obj('readonly').index('kind').getAll(kind);q.onsuccess=()=>res(q.result||[]);q.onerror=()=>rej(q.error)})}
async function put(x){await openDB();return new Promise((res,rej)=>{const q=obj('readwrite').put(x);q.onsuccess=()=>res(x);q.onerror=()=>rej(q.error)})}
async function del(id){await openDB();return new Promise((res,rej)=>{const q=obj('readwrite').delete(id);q.onsuccess=()=>res();q.onerror=()=>rej(q.error)})}
function notifySync(type,payload){try{const q=JSON.parse(localStorage.getItem('ccner-p1-sync')||'[]');q.push({id:uid('sync'),type,payload,createdAt:new Date().toISOString(),status:'pending'});localStorage.setItem('ccner-p1-sync',JSON.stringify(q.slice(-100)))}catch(_){} }
async function refresh(){try{stories=await all('story');music=await all('music')}catch(_){stories=[];music=[]}renderBody()}
function ensurePanel(){if($('#l1Panel'))return;document.body.insertAdjacentHTML('beforeend',`<section id="l1Panel" class="l1-modal" hidden><div class="l1-card"><button class="l1-close" id="l1Close" aria-label="Close">×</button><div class="l1-head"><div><span class="l1-kicker">MEMORY COMPANION</span><h2 id="l1Heading">${t('stories')}</h2><p id="l1Intro">${t('momo')}</p></div><div class="l1-tabs"><button class="active" data-l1-tab="stories">❤️ ${t('stories')}</button><button data-l1-tab="music">🎵 ${t('music')}</button></div></div><div id="l1Body"></div></div></section>`);$('#l1Close').onclick=close;$('#l1Panel').addEventListener('click',e=>{if(e.target.id==='l1Panel')close()});$$('[data-l1-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.l1Tab))}
let tab='stories';
function switchTab(k){tab=k;$$('[data-l1-tab]').forEach(b=>b.classList.toggle('active',b.dataset.l1Tab===k));if($('#l1Heading'))$('#l1Heading').textContent=k==='stories'?t('stories'):t('music');renderBody()}
function open(k='stories'){ensurePanel();$('#l1Panel').hidden=false;switchTab(k);refresh()}
function close(){stopAll();if($('#l1Panel'))$('#l1Panel').hidden=true}
function renderBody(){const b=$('#l1Body');if(!b)return;b.innerHTML=tab==='stories'?storyView():musicView();bindBody()}
function storyView(){return`<div class="l1-hero"><div><b>${t('family')}</b><p>Record a real family memory, upload an existing recording, name it, and keep it available for Momo and future replay.</p></div><div class="l1-actions"><button class="l1-primary" data-add="record">🎙️ ${t('record')}</button><button class="l1-secondary" data-add="story-upload">⬆️ ${t('upload')}</button></div></div><p class="l1-privacy">🔒 ${t('privacy')}</p><div id="l1StoryList" class="l1-list">${stories.length?stories.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(cardStory).join(''):`<div class="l1-empty">🐾 ${t('emptyStory')}</div>`}</div>`}
function cardStory(s){return`<article class="l1-item"><div class="l1-item-icon">❤️</div><div class="l1-item-main"><h3>${esc(s.title)}</h3><p>${new Date(s.createdAt).toLocaleDateString()} · ${s.duration?s.duration+'s':'Saved memory'}</p><div class="l1-item-tags"><span>Family</span><span>Real recording</span></div></div><div class="l1-item-actions"><button data-play="${esc(s.id)}">▶ ${t('play')}</button><button class="danger" data-del="${esc(s.id)}">${t('delete')}</button></div></article>`}
function musicView(){return`<div class="l1-hero"><div><b>${t('cue')}</b><p>Keep regional folk songs, familiar music, family-associated music, or culturally familiar sounds close to the person. Upload only music you are allowed to use.</p></div><div class="l1-actions"><button class="l1-primary" data-add="music-upload">🎵 ${t('addMusic')}</button></div></div><div class="l1-cue-grid"><button data-cue="bihu">🥁 Bihu-inspired rhythm cue</button><button data-cue="folk">🪕 NER folk-inspired melody cue</button><button data-cue="bell">🔔 Familiar home bell cue</button></div><p class="l1-privacy">Built-in cues are short generated memory prompts, not recordings of traditional songs. Add the person's real familiar music with the upload option.</p><div id="l1MusicList" class="l1-list">${music.length?music.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(cardMusic).join(''):`<div class="l1-empty">🎵 ${t('emptyMusic')}</div>`}</div>`}
function cardMusic(m){return`<article class="l1-item"><div class="l1-item-icon">🎵</div><div class="l1-item-main"><h3>${esc(m.title)}</h3><p>${esc(m.region||'')}${m.association?' · '+esc(m.association):''}</p><div class="l1-item-tags"><span>${esc(m.category||'Familiar music')}</span><span>${m.mimeType?'Uploaded':'Memory cue'}</span></div></div><div class="l1-item-actions"><button data-play="${esc(m.id)}">▶ ${t('play')}</button><button class="danger" data-del="${esc(m.id)}">${t('delete')}</button></div></article>`}
function bindBody(){$$('.l1-modal [data-add]').forEach(b=>b.onclick=()=>addForm(b.dataset.add));$$('[data-play]').forEach(b=>b.onclick=()=>playById(b.dataset.play));$$('[data-del]').forEach(b=>b.onclick=async()=>{await del(b.dataset.del);notifySync('level1-delete',{id:b.dataset.del});await refresh()});$$('[data-cue]').forEach(b=>b.onclick=()=>playCue(b.dataset.cue))}
function addForm(type){const story=type!=='music-upload',b=$('#l1Body');b.innerHTML=`<div class="l1-form-wrap"><button class="l1-back" id="l1Back">← ${t('cancel')}</button><h3>${story?t('addStory'):t('addMusic')}</h3><form id="l1Form"><label>${story?t('title'):t('musicTitle')}<input name="title" required maxlength="100" placeholder="${story?'Grandmother’s village story':'Bihu song / family favourite'}"></label>${!story?`<label>${t('region')}<input name="region" maxlength="80" placeholder="Assamese, Bengali, Arunachal…"></label><label>${t('association')}<input name="association" maxlength="120" placeholder="Mother used to sing this…"></label><label>Type<select name="category"><option>${t('folk')}</option><option>${t('familiar')}</option><option>${t('family')}</option><option>${t('sound')}</option></select></label>`:''}<label class="l1-file">${story?'Audio recording':'Music file'}<input id="l1File" name="file" type="file" accept="audio/*"></label>${story?`<div class="l1-record-box"><button type="button" id="l1StartRecord">🎙️ ${t('record')}</button><span id="l1RecordStatus"></span></div>`:''}<div class="l1-actions"><button type="button" class="l1-secondary" id="l1Back2">${t('cancel')}</button><button class="l1-primary" type="submit">${t('save')}</button></div></form></div>`;$('#l1Back').onclick=renderBody;$('#l1Back2').onclick=renderBody;$('#l1Form').onsubmit=e=>saveForm(e,story);if(story)$('#l1StartRecord').onclick=toggleRecording}
async function saveForm(e,story){e.preventDefault();const f=e.currentTarget,d=new FormData(f),file=d.get('file');let blob=file&&file.size?file:null;if(recorder&&recorder.state==='recording')await stopRecording();if(!blob&&window.__l1RecordedBlob)blob=window.__l1RecordedBlob;if(!blob){alert(story?'Please record or upload an audio file.':'Please upload an audio file.');return}const item={id:uid(story?'story':'music'),kind:story?'story':'music',title:String(d.get('title')||'').trim(),createdAt:new Date().toISOString(),duration:window.__l1RecordedDuration||0,mimeType:blob.type||'audio/webm',blob};if(!story){item.region=String(d.get('region')||'').trim();item.association=String(d.get('association')||'').trim();item.category=String(d.get('category')||'Familiar music')}await put(item);notifySync(story?'family-story':'music-memory',{id:item.id,title:item.title});window.__l1RecordedBlob=null;window.__l1RecordedDuration=0;tab=story?'stories':'music';await refresh();renderBody()}
async function toggleRecording(){if(recorder&&recorder.state==='recording'){await stopRecording();return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){$('#l1RecordStatus').textContent=t('notSupported');return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});recChunks=[];recStarted=Date.now();recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)recChunks.push(e.data)};recorder.onstop=()=>{stream.getTracks().forEach(x=>x.stop());const blob=new Blob(recChunks,{type:recorder.mimeType||'audio/webm'});window.__l1RecordedBlob=blob;window.__l1RecordedDuration=Math.round((Date.now()-recStarted)/100)/10;const s=$('#l1RecordStatus');if(s)s.textContent=`${t('save')} · ${window.__l1RecordedDuration}s`;const b=$('#l1StartRecord');if(b)b.textContent='🎙️ '+t('record')};recorder.start();const s=$('#l1RecordStatus');if(s)s.textContent=t('recording');const b=$('#l1StartRecord');if(b)b.textContent='⏹ '+t('stop')}catch(_){const s=$('#l1RecordStatus');if(s)s.textContent=t('notSupported')}}
function stopRecording(){return new Promise(resolve=>{if(!recorder||recorder.state!=='recording')return resolve();const r=recorder,old=r.onstop;r.onstop=()=>{try{old?.()}finally{resolve()}};r.stop()})}
function stopAll(){if(activeAudio){activeAudio.pause();activeAudio.src='';activeAudio=null}if(recorder&&recorder.state==='recording')recorder.stop()}
async function playById(id){const item=[...stories,...music].find(x=>x.id===id);if(!item)return;stopAll();if(item.blob){activeAudio=new Audio(URL.createObjectURL(item.blob));activeAudio.onended=()=>{activeAudio=null};await activeAudio.play().catch(()=>{});return}playCue(item.cue||'folk')}
function playCue(kind){stopAll();const C=window.AudioContext||window.webkitAudioContext;if(!C){alert('Audio playback is not supported in this browser.');return}const c=new C(),now=c.currentTime,patterns={bihu:[220,277,330,277,392,330,277,220],folk:[196,247,294,330,294,247,220,196],bell:[660,880,660,0,660]},seq=patterns[kind]||patterns.folk;seq.forEach((hz,i)=>{if(!hz)return;const o=c.createOscillator(),g=c.createGain();o.type=kind==='bell'?'sine':'triangle';o.frequency.value=hz;g.gain.setValueAtTime(.0001,now+i*.32);g.gain.exponentialRampToValueAtTime(.12,now+i*.32+.03);g.gain.exponentialRampToValueAtTime(.0001,now+i*.32+.25);o.connect(g).connect(c.destination);o.start(now+i*.32);o.stop(now+i*.32+.27)});setTimeout(()=>c.close().catch(()=>{}),seq.length*320+600)}
function matching(text){const q=String(text||'').toLowerCase(),keys=['family','story','memories','memory','grandmother','grandfather','mother','father','music','song','remember','याद','परिवार','कहानी','स्मृति','संगीत','পরিবার','স্মৃতি','গান','পৰিয়াল','স্মৃতি','গান'];return keys.some(k=>q.includes(k))?(stories.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt))[0]||null):null}
function momoMemory(text,container){const s=matching(text);if(!s)return false;const wrap=document.createElement('div');wrap.className='l1-momo-memory';wrap.innerHTML=`<span>❤️</span><div><b>Family memory</b><p>Here is a real family recording you saved: <strong>${esc(s.title)}</strong>.</p><button type="button" data-momo-play="${esc(s.id)}">▶ Play memory</button></div>`;container?.appendChild(wrap);wrap.querySelector('[data-momo-play]').onclick=()=>playById(s.id);return true}
function boot(){ensurePanel();window.CCNERLevel1={open,close,refresh,momoMemory,getRelevantStory:matching,playById,playCue}}
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot):boot();
})();